import unittest


class TestParseLabel(unittest.TestCase):
    def test_valid_fields_and_offsets(self):
        cases = [
            ('', [('', 0)]),
            (',,', [('', 0), ('', 1), ('', 2)]),
            ('red,"blue,green",',
             [('red', 0), ('blue,green', 4), ('', 17)]),
            ('"a""b", x', [('a"b', 0), (' x', 7)]),
            ('"",', [('', 0), ('', 3)]),
            ('  x ," y "', [('  x ', 0), (' y ', 5)]),
        ]
        for line, expected in cases:
            with self.subTest(line=line):
                self.assertEqual(parse_label(line), expected)

    def test_invalid_quotes(self):
        for line in ('"open', 'ab"cd', '"ok"x', '"ok" '):
            with self.subTest(line=line):
                with self.assertRaises(ValueError):
                    parse_label(line)


if __name__ == '__main__':
    unittest.main()
